### 1. Modifie la fonction `value` pour gérer la puissance

Remplace la fonction `value` par :

````rust
// filepath: /home/olivier/projets/luca/src/interpreter.rs
impl Parser {
    // ...

    /// value : atom (POWER value)?
    fn value(&mut self) -> Result<AST, Error> {
        let mut node = self.atom()?;

        // Gère la puissance à droite
        if self.current_token == Token::POWER {
            self.eat(&Token::POWER)?;
            let right = self.value()?;
            node = AST::new(Token::POWER, vec![node, right]);
        }

        // Après la puissance, gère l'unité, la monnaie ou le pourcentage
        match self.current_token.clone() {
            Token::MONEY(currency) => {
                self.eat(&Token::MONEY(currency))?;
                node = AST::new(Token::MONEY(currency), vec![node]);
            },
            Token::PERCENTAGE => {
                self.eat(&Token::PERCENTAGE)?;
                node = AST::new(Token::PERCENTAGE, vec![node]);
            },
            Token::UNIT(unit) => {
                self.eat(&Token::UNIT(unit))?;
                node = AST::new(Token::UNIT(unit), vec![node]);
            },
            _ => {}
        }

        Ok(node)
    }

    /// atom : NUMBER | UNIT | LPAREN expr RPAREN | VAR
    fn atom(&mut self) -> Result<AST, Error> {
        let token = self.current_token.clone();

        match token {
            Token::NUMBER(_) => self.number(),
            Token::UNIT(symbol) => {
                self.eat(&Token::UNIT(symbol))?;
                Ok(AST::new(Token::UNIT(symbol), vec![]))
            },
            Token::MONEY(currency) => {
                self.eat(&Token::MONEY(currency))?;
                Ok(AST::new(Token::MONEY(currency), vec![]))
            },
            Token::LPAREN => {
                self.eat(&Token::LPAREN)?;
                let node = self.expr()?;
                self.eat(&Token::RPAREN)?;
                Ok(node)
            },
            Token::VAR(name) => {
                self.eat(&Token::VAR(name.clone()))?;
                Ok(AST::new(Token::VAR(name), vec![]))
            },
            _ => Err(Error::InvalidSyntax)
        }
    }

    // ...le reste inchangé...
}
````

### 2. Dans `factor`, appelle `value()` au lieu de l’ancienne logique

````rust
// filepath: /home/olivier/projets/luca/src/interpreter.rs
impl Parser {
    // ...

    fn factor(&mut self) -> Result<AST, Error> {
        let token = self.current_token.clone();

        match token {
            Token::PLUS | Token::MINUS => {
                self.eat(&token)?;
                let children = vec![self.factor()?];
                Ok(AST::new(token, children))
            },
            _ => self.value()
        }
    }
}
````

